export namespace Effect {
  export interface Effect<A, E = never, R = never> {
    readonly _A: A
    readonly _E: E
    readonly _R: R
    pipe(...operations: ReadonlyArray<unknown>): Effect<unknown, unknown, unknown>
  }
}

export type Severity = "Error" | "Warning"

export const Effect: {
  fail<E>(value: E): Effect.Effect<never, E>
  ignore<A, E, R>(effect: Effect.Effect<A, E, R>, options?: { readonly log?: boolean | Severity }): Effect.Effect<void, never, R>
  ignore(options?: { readonly log?: boolean | Severity }): <A, E, R>(effect: Effect.Effect<A, E, R>) => Effect.Effect<void, never, R>
  ignoreCause<A, E, R>(effect: Effect.Effect<A, E, R>, options?: { readonly log?: boolean | Severity }): Effect.Effect<void, never, R>
  tapError<A, E, R>(self: Effect.Effect<A, E, R>, f: (error: E) => Effect.Effect<unknown>): Effect.Effect<A, E, R>
  tapError<E>(f: (error: E) => Effect.Effect<unknown>): (self: Effect.Effect<unknown, E>) => Effect.Effect<unknown, E>
  tapCause<A, E, R>(self: Effect.Effect<A, E, R>, f: (cause: unknown) => Effect.Effect<unknown>): Effect.Effect<A, E, R>
  tapCause<E>(f: (cause: unknown) => Effect.Effect<unknown>): (self: Effect.Effect<unknown, E>) => Effect.Effect<unknown, E>
  andThen<A, E, R>(next: Effect.Effect<A, E, R>): (self: Effect.Effect<unknown>) => Effect.Effect<A, E, R>
  logError(error: unknown): Effect.Effect<void>
}
